  const mountedRef = React.useRef(false);
  React.useEffect(() => {
    let frame = requestAnimationFrame(() => {
      frame = requestAnimationFrame(() => {
        mountedRef.current = true;
      });
    });
    return () => {
      cancelAnimationFrame(frame);
      mountedRef.current = false;
