          { opacity: 1, filter: 'blur(0px)', transform: 'translateY(0px)' },
        ],
        options,
      );
      return {
        animation,
        stop: () => {
          animation.cancel();
          incoming.remove();
          el.style.opacity = opacity;
        },
      };
    });
    text = next;
    copy = el.cloneNode(true) as HTMLElement;
    box = boxOf(el);
