  if (clear && !saved) {
    savedStyles.set(node, save(node, SURFACE_PROPERTIES));
    node.style.setProperty('background-color', 'transparent', 'important');
    node.style.setProperty('background-image', 'none', 'important');
  } else if (!clear && saved) {
    savedStyles.delete(node);
    restore(node, saved);
  }
}

const isBare = ({ backgroundColor, backgroundImage }: Surface) =>
  backgroundImage === 'none' &&
  (backgroundColor === 'transparent' ||
    /^rgba\(.*,\s*0\)$/.test(backgroundColor));

/** A surface painted in the color behind it shows nothing: a highlight may glide over it. */
function blendsIn(node: HTMLElement, surface: Surface) {
  if (surface.backgroundImage !== 'none' || isBare(surface)) return false;
  for (let el = node.parentElement; el; el = el.parentElement) {
    const style = getComputedStyle(el);
    if (style.backgroundImage !== 'none') return false;
    const backdrop = { ...surface, backgroundColor: style.backgroundColor };
    if (!isBare(backdrop))
      return style.backgroundColor === surface.backgroundColor;
  }
  return false;
}

function readSurface(node: HTMLElement): Surface {
  const cleared = savedStyles.get(node);
  const transition = save(node, ['transition']);
  node.style.setProperty('transition', 'none', 'important');
  if (cleared) restore(node, cleared);
  const style = getComputedStyle(node);
  const surface = {
    backgroundColor: style.backgroundColor,
    backgroundImage: style.backgroundImage,
    borderRadius: style.borderRadius,
  };
  if (cleared) {
    node.style.setProperty('background-color', 'transparent', 'important');
    node.style.setProperty('background-image', 'none', 'important');
  }
  void getComputedStyle(node).backgroundColor;
  restore(node, transition);
  return surface;
}

const isExpanded = (node: HTMLElement) =>
  node.getAttribute('aria-expanded') === 'true';

const without = (list: readonly Leaving[], id: string) =>
  list.some((other) => other.id === id)
    ? list.filter((other) => other.id !== id)
    : list;

function clipperOf(item: HTMLElement) {
  const body = item.ownerDocument.body;
  for (let el = item.parentElement; el && el !== body; el = el.parentElement) {
    const { overflowX, overflowY } = getComputedStyle(el);
    if (overflowX !== 'visible' || overflowY !== 'visible') return el;
  }
  return null;
}

const crossesClip = (from: HTMLElement, to: HTMLElement) =>
  clipperOf(from) !== clipperOf(to);

// Out of a clipped box into the one around it, the one leaving is cut on the
// way: it fades out under the one coming in, whole at once. Otherwise the one
// coming in fades in over the one leaving.
const comesOut = (from: HTMLElement, to: HTMLElement) => {
  const inner = clipperOf(from);
  const outer = clipperOf(to);
  return !!inner && !inner.contains(to) && (!outer || outer.contains(from));
};

type ItemHighlight = {
  ref: (node: HTMLElement | null) => void;
  highlight: React.ReactNode;
};

type ItemHighlightOptions = {
  attribute?: string;
  followFocus?: boolean;
};

type TriggerHighlightOptions = {
  beside?: boolean;
};

function useItemHighlight(
  disabled?: boolean,
  {
    attribute = 'data-highlighted',
    followFocus = false,
  }: ItemHighlightOptions = {},
): ItemHighlight {
  return useHighlightIn(
    React.use(HighlightScopeContext),
    disabled,
    attribute,
    false,
    followFocus,
  );
}

function useTriggerHighlight(
  disabled?: boolean,
  { beside = false }: TriggerHighlightOptions = {},
): ItemHighlight {
  return useHighlightIn(React.use(TriggerScopeContext), disabled, null, beside);
}

const samePaint = (a: Surface | null, b: Surface) =>
  a !== null &&
  a.backgroundColor === b.backgroundColor &&
  a.backgroundImage === b.backgroundImage &&
  a.borderRadius === b.borderRadius;

const TRIGGER_ATTRIBUTES = [
  'aria-expanded',
  'data-state',
  'data-highlighted',
  'data-popup-open',
  'data-pressed',
  'data-disabled',
];

function useHighlightIn(
  scope: HighlightScopeValue | null,
  disabled: boolean | undefined,
  attribute: string | null,
  beside = false,
  followFocus = false,
): ItemHighlight {
  const id = React.useId();
  const [node, setNode] = React.useState<HTMLElement | null>(null);
  const [surface, setSurface] = React.useState<Surface | null>(null);
  const paint = scope?.paint;
  const light = scope?.light;
  const unlight = scope?.unlight;
  const ref = React.useCallback((element: HTMLElement | null) => {
    if (element)
      setNode((current) => (current === element ? current : element));
  }, []);

  React.useLayoutEffect(() => {
    if (attribute !== null || !light || !unlight || !node) return;
    if (!beside && getComputedStyle(node).position === 'static')
      node.style.setProperty('position', 'relative');
    let hovered = false;
    let lit = false;
    let frame = 0;
    const sync = () => {
      const interactive =
        !disabled && (hovered || isExpanded(node) || node.matches(':focus'));
      if (interactive) clearOwnSurface(node, true);
      const surface = interactive ? readSurface(node) : null;
      const now = surface !== null && !isBare(surface);
      if (surface && now)
        setSurface((current) =>
          samePaint(current, surface) ? current : surface,
        );
      clearOwnSurface(
        node,
        now || (!interactive && blendsIn(node, readSurface(node))),
      );
      if (now === lit) return;
      lit = now;
      if (now) light(id, node);
      else unlight(id);
    };
    const enter = () => {
      hovered = true;
      sync();
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(sync);
    };
    const leave = () => {
      hovered = false;
      cancelAnimationFrame(frame);
      sync();
    };
    sync();
    const observer = new MutationObserver(sync);
    observer.observe(node, {
      attributes: true,
      attributeFilter: TRIGGER_ATTRIBUTES,
    });
    node.addEventListener('pointerenter', enter);
    node.addEventListener('pointerleave', leave);
    node.addEventListener('focus', sync);
    node.addEventListener('blur', sync);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      node.removeEventListener('pointerenter', enter);
      node.removeEventListener('pointerleave', leave);
      node.removeEventListener('focus', sync);
      node.removeEventListener('blur', sync);
      clearOwnSurface(node, false);
      if (lit) unlight(id);
    };
  }, [attribute, light, unlight, node, id, disabled, beside]);

  React.useLayoutEffect(() => {
    if (attribute === null || !light || !unlight || !paint || !node) return;
    if (getComputedStyle(node).position === 'static')
      node.style.setProperty('position', 'relative');

    const clear = () =>
      clearOwnSurface(
        node,
        node.hasAttribute(attribute) ||
          isExpanded(node) ||
          node.matches(':focus'),
      );
    const sync = () => {
      if (node.hasAttribute(attribute)) {
        setSurface(paint(readSurface(node)));
        light(id, node);
      } else if (followFocus) unlight(id);
      clear();
    };
    const focus = () => {
      if (node.hasAttribute(attribute)) setSurface(paint(readSurface(node)));
      clear();
    };
    sync();
    const observer = new MutationObserver(sync);
    observer.observe(node, {
      attributes: true,
      attributeFilter: [attribute, 'aria-expanded'],
    });
    node.addEventListener('focus', focus);
    node.addEventListener('blur', clear);
    return () => {
      observer.disconnect();
      node.removeEventListener('focus', focus);
      node.removeEventListener('blur', clear);
      clearOwnSurface(node, false);
    };
  }, [light, unlight, paint, node, id, attribute, followFocus]);

  const active = scope?.activeId === id && !disabled;
  const leaving =
    (!disabled && scope?.leaving.find((other) => other.id === id)) || null;

  return {
    ref,
    highlight: scope ? (
      <HighlightSurface
        id={id}
        surface={surface}
        active={active}
        leaving={leaving}
        item={node}
        scope={scope}
        beside={beside}
      />
    ) : null,
  };
}

type HighlightSurfaceProps = {
  id: string;
  surface: Surface | null;
  active: boolean;
  leaving: Leaving | null;
  item: HTMLElement | null;
  scope: HighlightScopeValue;
  beside: boolean;
};

function HighlightSurface({
  id,
  surface,
  active,
  leaving,
  item,
  scope,
  beside,
}: HighlightSurfaceProps) {
  if (!surface || !item) return null;
  return (
    <>
      {active && (
        <SurfaceCopy
          key="active"
          id={id}
          surface={surface}
          item={item}
          scope={scope}
          beside={beside}
        />
      )}
      {leaving && !active && (
        <SurfaceCopy
          key={`leaving-${leaving.key}`}
          id={id}
          surface={surface}
          item={item}
          scope={scope}
          beside={beside}
          leavingTo={leaving.to}
          fadeOut={leaving.to === null}
        />
      )}
    </>
  );
}

function placeOver(element: HTMLElement, item: HTMLElement) {
  const host = element.offsetParent as HTMLElement | null;
  const box = item.getBoundingClientRect();
  const origin = host?.getBoundingClientRect();
  const { x: ratioX, y: ratioY } =
    host && origin ? layoutScale(host, origin) : { x: 1, y: 1 };
  const left = origin
    ? (box.left - origin.left) / ratioX - host!.clientLeft + host!.scrollLeft
    : box.left + window.scrollX;
  const top = origin
    ? (box.top - origin.top) / ratioY - host!.clientTop + host!.scrollTop
    : box.top + window.scrollY;
  element.style.left = `${left}px`;
  element.style.top = `${top}px`;
  element.style.width = `${box.width / ratioX}px`;
  element.style.height = `${box.height / ratioY}px`;
}

function useBesideBox(
  elementRef: React.RefObject<HTMLElement | null>,
  item: HTMLElement,
  beside: boolean,
) {
  React.useLayoutEffect(() => {
    const element = elementRef.current;
    if (!beside || !element) return;
    const place = () => placeOver(element, item);
    place();
    const observer = new ResizeObserver(place);
    observer.observe(item);
    if (element.offsetParent) observer.observe(element.offsetParent);
    return () => observer.disconnect();
  }, [elementRef, item, beside]);
}

type Start = {
  offset: Offset;
  opacity: number;
  color: string | null;
  fresh: boolean;
  velocity: Offset;
  cross: boolean;
  enters: boolean;
};

const IN_PLACE: Offset = { x: 0, y: 0, scaleX: 1, scaleY: 1 };
const STILL: Offset = { x: 0, y: 0, scaleX: 0, scaleY: 0 };

function velocityOf({ animation, ease, duration, from }: Glide): Offset {
  const time = Number(animation.currentTime ?? duration);
  if (!(time < duration)) return STILL;
  const step = 4;
  const before = Math.max(0, time - step);
  const rate =
    (ease(Math.min(1, (before + step) / duration)) - ease(before / duration)) /
    step;
  return {
    x: -from.x * rate,
    y: -from.y * rate,
    scaleX: (1 - from.scaleX) * rate,
    scaleY: (1 - from.scaleY) * rate,
  };
}

function handOff(
  previous: SurfaceHandle | null,
  item: HTMLElement,
  reduce: boolean,
): Start {
  if (!previous?.element.isConnected)
    return {
      offset: IN_PLACE,
      opacity: 0,
      color: null,
      fresh: true,
      velocity: STILL,
      cross: false,
      enters: false,
    };
  const style = getComputedStyle(previous.element);
  const opacity = Number(style.opacity);
  const color = style.backgroundColor;
  const cross = crossesClip(previous.item, item);
  const enters = cross && !comesOut(previous.item, item);
  const offset = offsetOn(previous.element.getBoundingClientRect(), item);
  if (reduce || !offset)
    return {
      offset: IN_PLACE,
      opacity,
      color,
      fresh: false,
      velocity: STILL,
      cross,
      enters,
    };

  const own = item.getBoundingClientRect();
  const from = previous.item.getBoundingClientRect();
  const velocity = previous.glide ? velocityOf(previous.glide) : STILL;
  return {
    offset,
    opacity,
    color,
    fresh: false,
    velocity: {
      x: velocity.x,
      y: velocity.y,
      scaleX: (velocity.scaleX * from.width) / own.width,
      scaleY: (velocity.scaleY * from.height) / own.height,
    },
    cross,
    enters,
  };
}

function offsetOn(box: DOMRect, item: HTMLElement): Offset | null {
  const own = item.getBoundingClientRect();
  if (!own.width || !own.height) return null;
  const ratioX = own.width / (item.offsetWidth || own.width);
  const ratioY = own.height / (item.offsetHeight || own.height);
  return {
    x: (box.left - own.left) / ratioX,
    y: (box.top - own.top) / ratioY,
    scaleX: box.width / own.width,
    scaleY: box.height / own.height,
  };
}

function initialRate(
  { offset, velocity }: Start,
  to: Offset,
  width: number,
  height: number,
) {
  const way = [
    to.x - offset.x,
    to.y - offset.y,
    (to.scaleX - offset.scaleX) * width,
    (to.scaleY - offset.scaleY) * height,
  ];
  const speed = [
    velocity.x,
    velocity.y,
    velocity.scaleX * width,
    velocity.scaleY * height,
  ];
  const length = way.reduce((sum, d) => sum + d * d, 0);
  if (length < 0.25) return null;
  return way.reduce((sum, d, i) => sum + d * speed[i]!, 0) / length;
}

const toTransform = ({ x, y, scaleX, scaleY }: Offset) =>
  `translate(${x}px, ${y}px) scale(${scaleX}, ${scaleY})`;

type SurfaceCopyProps = {
  id: string;
  surface: Surface;
  item: HTMLElement;
  scope: HighlightScopeValue;
  leavingTo?: HTMLElement | null;
  fadeOut?: boolean;
  beside?: boolean;
};

function SurfaceCopy({
  id,
  surface,
  item,
  scope,
  leavingTo = null,
  fadeOut = false,
  beside = false,
}: SurfaceCopyProps) {
  const reduce = useShouldReduceMotion();
  const glide = useTempoTransition<Transition>(HIGHLIGHT_TRANSITION);
  const fade = useTempoTransition<Transition>(FADE_TRANSITION);
  const resume = useTempoTransition<Transition>(RESUME_TRANSITION);
  const [start] = React.useState(() => scope.handOff(item, reduce));
  const [target] = React.useState(() =>
    leavingTo && !reduce
      ? offsetOn(leavingTo.getBoundingClientRect(), item)
      : null,
  );
  const elementRef = React.useRef<HTMLSpanElement>(null);
  const transitionsRef = React.useRef({ glide, fade, resume });
  const { register, gone, left } = scope;
  useBesideBox(elementRef, item, beside);

  React.useLayoutEffect(() => {
    const element = elementRef.current;
    if (!element) return undefined;
    const animations: Animation[] = [];
    let running: Glide | null = null;
    if (leavingTo && !target) {
      left(id);
      return undefined;
    }

    const to = target ?? IN_PLACE;
    const rate = initialRate(start, to, item.offsetWidth, item.offsetHeight);
    let timing: { duration: number; easing: string } | null = null;
    if (rate !== null) {
      const { ease, duration } = createGeneratorEasing(
        { ...transitionsRef.current.glide, velocity: rate * 1000 * 100 },
        100,
        springGenerator,
      );
      const ms = duration * 1000;
      timing = { duration: ms, easing: generateLinearEasing(ease, ms) };
      const animation = element.animate(
        [
          { transform: toTransform(start.offset) },
          { transform: target ? toTransform(target) : 'none' },
        ],
        { ...timing, fill: target ? 'forwards' : 'auto' },
      );
      animations.push(animation);
      running = { animation, ease, duration: ms, from: start.offset };
    }

    if (target) {
      if (running && comesOut(item, leavingTo!))
        animations.push(
          element.animate([{ opacity: 1 }, { opacity: 0 }], {
            ...timing!,
            fill: 'forwards',
          }),
        );
      if (running)
        running.animation.finished.then(
          () => left(id),
          () => {},
        );
      else left(id);
      return () => {
        for (const animation of animations) animation.cancel();
      };
    }

    // An item still coming in with its list's stagger: its highlight shows once it has landed.
    const landing = staggerLeft(element.parentElement);
    if (fadeOut) {
      const { duration, easing } = toCssTiming(transitionsRef.current.fade);
      const fading = element.animate(
        [{ opacity: start.opacity }, { opacity: 0 }],
        { duration, easing, fill: 'forwards' },
      );
      animations.push(fading);
      fading.finished.then(
        () => left(id),
        () => {},
      );
    } else if (start.enters && timing) {
      animations.push(
        element.animate([{ opacity: 0 }, { opacity: 1 }], timing),
      );
    } else if (start.opacity < 1 || landing > 0) {
      const { duration, easing } = toCssTiming(
        start.fresh || landing > 0
          ? transitionsRef.current.fade
          : transitionsRef.current.resume,
      );
      animations.push(
        element.animate(
          [{ opacity: landing > 0 ? 0 : start.opacity }, { opacity: 1 }],
          { duration, easing, delay: landing, fill: 'backwards' },
        ),
      );
    }

    const color = getComputedStyle(element).backgroundColor;
    if (start.color && start.color !== color && !target) {
      const { duration, easing } = toCssTiming(transitionsRef.current.fade);
      animations.push(
        element.animate(
          [{ backgroundColor: start.color }, { backgroundColor: color }],
          { duration, easing },
        ),
      );
    }

    const unregister = register({ id, element, item, glide: running });
    return () => {
      const opacity = element.isConnected
        ? Number(getComputedStyle(element).opacity)
        : 0;
      for (const animation of animations) animation.cancel();
      unregister();
      gone(opacity);
    };
  }, [register, gone, left, id, item, start, target, leavingTo, fadeOut]);

  const { duration: colorDuration, easing: colorEasing } = toCssTiming(fade);

  return (
    <span
      ref={elementRef}
      aria-hidden
      data-slot={scope.slot}
      data-leaving={leavingTo || fadeOut ? '' : undefined}
      style={{
        position: 'absolute',
        ...(!beside && { inset: 0 }),
        zIndex: -1,
        pointerEvents: 'none',
        transformOrigin: '0 0',
        borderRadius: surface.borderRadius,
        backgroundColor: surface.backgroundColor,
        backgroundImage: surface.backgroundImage,
        transition: `background-color ${colorDuration}ms ${colorEasing}`,
      }}
    />
  );
}

function withHighlight(
  children: React.ReactNode,
  highlight: React.ReactNode,
  asChild?: boolean,
): React.ReactNode {
  if (!highlight) return children;
  if (asChild && React.isValidElement<{ children?: React.ReactNode }>(children))
    return React.cloneElement(
      children,
      undefined,
      <>
        {children.props.children}
        {highlight}
      </>,
    );
  return (
    <>
      {children}
      {highlight}
    </>
  );
}

export {
  HighlightScope,
  TriggerHighlightScope,
  useItemHighlight,
  useTriggerHighlight,
  withHighlight,
  HIGHLIGHT_TRANSITION,
  type ItemHighlight,
  type TriggerHighlightOptions,
};

'use client';

import * as React from 'react';
import { PresenceContext, type Transition } from 'motion/react';

import {
  motionTokens,
  useCheckAnimation,
  useShouldReduceMotion,
  useTempoTransition,
  type CheckAnimation,
} from '../utils/motion';
import {
  IndicatorContent,
  mergeRefs,
  type IndicatorContentProps,
  type IndicatorHandle,
} from './controls/indicator';
import { glideFrom, stopGlide } from './glide';

const DRAW_TRANSITION: Transition = {
  ...motionTokens.transition.check,
  delay: 0,
};
const ERASE_TRANSITION: Transition = motionTokens.transition.uncheck;
const POP_TRANSITION: Transition = motionTokens.spring.checkPop;
const UNPOP_TRANSITION: Transition = motionTokens.transition.popOut;

const GLIDE_TRANSITION = motionTokens.spring.highlight;

const PICK_HOLD: Record<CheckAnimation, number> = { draw: 0.25, pop: 0.15 };

type Picked = CheckAnimation | false;

function usePickHold() {
  const { delay: draw = 0 } = useTempoTransition({ delay: PICK_HOLD.draw });
  const { delay: pop = 0 } = useTempoTransition({ delay: PICK_HOLD.pop });
  return (look: CheckAnimation) => (look === 'draw' ? draw : pop);
}

type ItemCheckAnimationProps = {
  animation?: CheckAnimation;
  transition?: Transition;
};

type GroupReport = {
  handle: IndicatorHandle;
  shown: boolean;
  reduce: boolean;
  glide: Transition;
  rect?: DOMRect;
};

type CheckGroup = { report: (report: GroupReport) => void };

function createCheckGroup(): CheckGroup {
  let pending: GroupReport[] = [];
  const settle = () => {
    const reports = pending;
    pending = [];
    const last = new Map(reports.map((r) => [r.handle.element, r]));
    const shown = [...last.values()].filter((r) => r.shown);
    const hidden = [...last.values()].filter((r) => !r.shown);
    const to = shown.length === 1 ? shown[0]! : null;
    const from =
      to && !to.reduce ? hidden.find((r) => r.handle.isShown()) : undefined;
    if (to && from) {
      const start = from.rect ?? from.handle.element.getBoundingClientRect();
      for (const r of hidden) {
        stopGlide(r.handle.element);
        r.handle.toggle(false, false);
      }
      to.handle.toggle(true, false);
      glideFrom(to.handle.element, start, to.glide);
      return;
    }
    for (const r of hidden) r.handle.toggle(false, true);
    for (const r of shown) r.handle.toggle(true, true);
  };
  return {
    report: (report) => {
      if (pending.length === 0) queueMicrotask(settle);
      pending.push(report);
    },
  };
}

function useCheckGroup(): CheckGroup {
  const [group] = React.useState(createCheckGroup);
  return group;
}

type RegisterCheck = (element: Element, look: CheckAnimation) => () => void;

const CheckRegistryContext = React.createContext<RegisterCheck | null>(null);

function useCheckRegistry() {
  const checksRef = React.useRef(new Map<Element, CheckAnimation>());
  const registerCheck = React.useCallback<RegisterCheck>((element, look) => {
    checksRef.current.set(element, look);
    return () => {
      checksRef.current.delete(element);
    };
  }, []);
  const checkOf = React.useCallback((item?: Element | null): Picked => {
    let found: Picked = false;
    for (const [check, look] of checksRef.current) {
      if (item && !item.contains(check)) continue;
      if (look === 'draw') return 'draw';
      found = look;
    }
    return found;
  }, []);
  const hasCheck = React.useCallback(
    (item?: Element | null) => checkOf(item) !== false,
    [checkOf],
  );
  return { registerCheck, hasCheck, checkOf };
}

type ItemCheckProps = Omit<
  IndicatorContentProps,
  'kind' | 'animation' | 'transition' | 'exitTransition' | 'coordinate'
> &
  ItemCheckAnimationProps & {
    multiple: boolean;
    group: CheckGroup | null;
  };

const settledLists = new WeakSet<Element>();

function inSettledList(check: Element | null) {
  const list = check?.closest('[role="menu"], [role="listbox"]');
  if (!list) return true;
  if (settledLists.has(list)) return true;
  requestAnimationFrame(() => settledLists.add(list));
  return false;
}

function ItemCheck({
  multiple,
  group,
  animation,
  transition,
  ref,
  ...props
}: ItemCheckProps) {
  const look = useCheckAnimation(animation);
  const reduce = useShouldReduceMotion();
  const glide = useTempoTransition(transition ?? GLIDE_TRANSITION);
  const gliding = look === 'pop' && !multiple && group !== null;
  const register = React.use(CheckRegistryContext);
  const elementRef = React.useRef<HTMLElement>(null);
  React.useLayoutEffect(() => {
    const element = elementRef.current;
    return element && register ? register(element, look) : undefined;
  }, [register, look]);
  const mergedRef = React.useMemo(
    () =>
      mergeRefs<HTMLElement>(
        ref as React.Ref<HTMLElement> | undefined,
        elementRef,
        gliding ? asTransformable : undefined,
      ),
    [ref, gliding],
  );
  const coordinate = React.useCallback(
    (handle: IndicatorHandle, shown: boolean) =>
      group?.report({ handle, shown, reduce, glide }),
    [group, reduce, glide],
  );
  const latestRef = React.useRef({ checked: props.checked, reduce, glide });
  React.useLayoutEffect(() => {
    latestRef.current = { checked: props.checked, reduce, glide };
  });
  React.useLayoutEffect(() => {
    const element = elementRef.current;
    if (!gliding || !group || !element) return undefined;
    return () => {
      const { checked, ...latest } = latestRef.current;
      if (!checked || !element.isConnected) return;
      group.report({
        handle: { element, toggle: () => {}, isShown: () => true },
        shown: false,
        rect: element.getBoundingClientRect(),
        ...latest,
      });
    };
  }, [gliding, group]);
  const [enter, exit] =
    look === 'pop'
      ? [POP_TRANSITION, UNPOP_TRANSITION]
      : [DRAW_TRANSITION, ERASE_TRANSITION];

  return (
    <PresenceContext value={null}>
      <IndicatorContent
        {...props}
        ref={mergedRef}
        kind="check"
        animation={look}
        transition={transition ?? enter}
        exitTransition={transition ?? exit}
        coordinate={gliding ? coordinate : undefined}
        animateOnMount={() => inSettledList(elementRef.current)}
      />
    </PresenceContext>
  );
}

function asTransformable(node: HTMLElement | null) {
  if (!node || getComputedStyle(node).display !== 'inline') return;
  const alone = node.parentElement?.childNodes.length === 1;
  node.style.setProperty('display', alone ? 'block' : 'inline-block');
}

type Picks = {
  markPick: (look: CheckAnimation) => void;
  hasCheck: (item?: Element | null) => boolean;
  checkOf: (item?: Element | null) => Picked;
};

const PickContext = React.createContext<Picks | null>(null);

function usePicks() {
  const { registerCheck, hasCheck, checkOf } = useCheckRegistry();
  const pickingRef = React.useRef<Picked>(false);
  const markPick = React.useCallback((look: CheckAnimation) => {
    if (pickingRef.current !== 'draw') pickingRef.current = look;
    setTimeout(() => {
      pickingRef.current = false;
    });
  }, []);
  const wasPicked = React.useCallback(() => pickingRef.current, []);
  const picks = React.useMemo(
    () => ({ markPick, hasCheck, checkOf }),
    [markPick, hasCheck, checkOf],
  );
  return { picks, registerCheck, wasPicked };
}

export {
  GLIDE_TRANSITION,
  PICK_HOLD,
  CheckRegistryContext,
  usePickHold,
  ItemCheck,
  PickContext,
  useCheckGroup,
  useCheckRegistry,
  usePicks,
  type CheckGroup,
  type ItemCheckAnimationProps,
  type ItemCheckProps,
  type Picked,
