const LOOK = [
  ...SIDES.flatMap((side) => [
    `border-${side.toLowerCase()}-width`,
    `border-${side.toLowerCase()}-style`,
    `border-${side.toLowerCase()}-color`,
  ]),
  'border-top-left-radius',
  'border-top-right-radius',
  'border-bottom-right-radius',
  'border-bottom-left-radius',
  'background-color',
  'background-image',
  'box-shadow',
