      if (!same(natural, end)) end = natural;
      glide = run(from, end, timing);
      glide.startTime = started;
      waiting = glide;
      return;
    }
    let now = end;
    let velocity = 0;
    let elapsed = 0;
    const running = !!glide && glide.playState !== 'finished';
