  let high = 1;
  for (let i = 0; i < 8; i++) {
    const share = (low + high) / 2;
    if (within(share)) low = share;
    else high = share;
  }
  return speed * low;
}

function curveFrom(
  transition: Transition,
  offset: number[],
  velocity: number[],
): Curve {
  return curveOf(transition, startOf(transition, offset, velocity));
}

