            config.zIndex ?? -1,
            config.fadeBackground
              ? `background-color ${color.duration}ms ${color.easing}`
              : 'none',
          ),
        }}
      />
    </>
  ) : null;

  return {
    indicator,
    ready,
    settling: ready && !settled,
  };
}

export {
  useSlidingIndicator,
  layoutSizeOf,
  SLIDING_ATTRIBUTE,
  LEAVING_ATTRIBUTE,
  onNextFrame,
  startNow,
  isRunning,
  type SlidingIndicatorConfig,
  type SlidingIndicatorOptions,
};

function screenScale(element: Element | null): [number, number] {
  if (!(element instanceof HTMLElement)) return [1, 1];
  const rect = element.getBoundingClientRect();
  const ratio = (drawn: number, laid: number) =>
    laid && Math.abs(drawn - laid) >= 1 ? drawn / laid : 1;
  return [
    ratio(rect.width, element.offsetWidth),
    ratio(rect.height, element.offsetHeight),
  ];
}

function layoutHeight(element: HTMLElement) {
  const drawn = element.getBoundingClientRect().height || 0;
  return drawn / screenScale(element)[1];
}

export { layoutHeight, screenScale };

import * as React from 'react';

function getStrictContext<T>(
  name?: string,
): readonly [
  ({
    value,
    children,
  }: {
    value: T;
    children?: React.ReactNode;
  }) => React.JSX.Element,
  () => T,
] {
  const Context = React.createContext<T | undefined>(undefined);

  const Provider = ({
    value,
    children,
  }: {
    value: T;
    children?: React.ReactNode;
  }) => <Context.Provider value={value}>{children}</Context.Provider>;

  const useSafeContext = () => {
    const ctx = React.useContext(Context);
    if (ctx === undefined) {
      throw new Error(`useContext must be used within ${name ?? 'a Provider'}`);
    }
    return ctx;
  };

  return [Provider, useSafeContext] as const;
}

export { getStrictContext };

